(7223117, 1113635, 47378, '<td valign="top">I like the motion blur here. Even the lens flare works for the shot.</td>', 'I like the motion blur here. Even the lens flare works for the shot.', '2014-06-01 01:37:29.000000', NULL, 1),
(7223120, 1115018, 89774, '<td valign="top">I love the quality and feel to this image.</td>', 'I love the quality and feel to this image.', '2014-06-01 01:43:40.000000', NULL, 1),
(7223123, 1114672, 89774, '<td valign="top">I need my sunglasses for this one. Is that a field of alfalfa? I like the way the colors graduate from the rising sun into the blue.</td>', 'I need my sunglasses for this one. Is that a field of alfalfa? I like the way the colors graduate from the rising sun into the blue.', '2014-06-01 01:49:34.000000', NULL, 1),
(7223125, 1115161, 89774, '<td valign="top">Great title!</td>', 'Great title!', '2014-06-01 01:51:10.000000', NULL, 1),
(7223126, 1115182, 117534, '<td valign="top">I really love your composition, and the processing of this, the one suggestion I would make is the whole shot is wonderful and soft feeling, but the foals coats where you can see the detail is a bit course, I probably would have put a softening filter on them and then erased thru the eyes. The catch light in the eyes are wonderful!!!</td>', 'I really love your composition, and the processing of this, the one suggestion I would make is the whole shot is wonderful and soft feeling, but the foals coats where you can see the detail is a bit course, I probably would have put a softening filter on them and then erased thru the eyes. The catch light in the eyes are wonderful!!!', '2014-06-01 02:09:24.000000', NULL, 1),
(7223131, 1113432, 108580, '<td valign="top">As a BiF photographer this is the first image that caught my eye whilst looking at the thumbnails. Notoriously shy and difficult to get close to before they fly off, the Hoopoe is a beautiful bird. Wonderful capture. I like the inclusion in your crop of the flying bee but it might hurt you with the composition police.</td>', 'As a BiF photographer this is the first image that caught my eye whilst looking at the thumbnails. Notoriously shy and difficult to get close to before they fly off, the Hoopoe is a beautiful bird. Wonderful capture. I like the inclusion in your crop of the flying bee but it might hurt you with the composition police.', '2014-06-01 02:59:40.000000', NULL, 1),
(7223132, 1114093, 108580, '<td valign="top">Hope you weren''t on foot! Beautiful scene in what appears to be the wild.</td>', 'Hope you weren''t on foot! Beautiful scene in what appears to be the wild.', '2014-06-01 03:02:04.000000', NULL, 1),
(7223135, 1114642, 108580, '<td valign="top">He''s hard to spot. Stunning colours and unusual landscape.</td>', 'He''s hard to spot. Stunning colours and unusual landscape.', '2014-06-01 03:25:30.000000', NULL, 1),
