(7225757, 1115009, 30982, '<td valign="top">Top ten in a FS, and yet another significantly above 6 - you''ve been on such a good roll of late!  Congrats!</td>', 'Top ten in a FS, and yet another significantly above 6 - you''ve been on such a good roll of late!  Congrats!', '2014-06-08 01:16:36.000000', NULL, 0),
(7225758, 1115139, 117534, '<td valign="top">I am so glad you got this shot! I have a male and female in my woods, I get glances at them and hear them do that crazy woody woodpecker call, but I''ve yet to get close enough to see much less photograph one! Thanks for this!!!!  Congrats on the high score (YA TURD) LOL</td>', 'I am so glad you got this shot! I have a male and female in my woods, I get glances at them and hear them do that crazy woody woodpecker call, but I''ve yet to get close enough to see much less photograph one! Thanks for this!!!!  Congrats on the high score (YA TURD) LOL', '2014-06-08 01:18:31.000000', NULL, 0),
(7225759, 1115009, 19825, '<td valign="top">Striking portrait, Sarah. Congrats on the excellent finish.</td>', 'Striking portrait, Sarah. Congrats on the excellent finish.', '2014-06-08 01:20:10.000000', NULL, 0),
